#!/bin/sh
# One-time setup: create deploy/.env with strong random secrets.
# Re-running never overwrites an existing .env (that would lock you out of
# the database and n8n's encrypted credentials).
set -eu
cd "$(dirname "$0")"

if [ -f .env ]; then
  echo "deploy/.env already exists — leaving it unchanged."
  exit 0
fi

secret() {
  # URL-safe characters only (n8n-init.sh and DATABASE_URL rely on this).
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex "$1"
  else
    head -c "$1" /dev/urandom | od -An -tx1 | tr -d ' \n'
  fi
}

umask 077
cat > .env <<EOF
# Generated by deploy/setup.sh on $(date -u +%Y-%m-%d). Keep this file private and backed up:
# losing N8N_ENCRYPTION_KEY or POSTGRES_PASSWORD means losing access to existing data.

# --- AI providers (fill in at least one) ---------------------------------
GEMINI_API_KEY=
ANTHROPIC_API_KEY=
OPENAI_API_KEY=
LLM_PROVIDER=gemini
GEMINI_MODEL=gemini-3.8-flash
CLAUDE_MODEL=claude-opus-4-7

# --- Secrets (generated) -------------------------------------------------
POSTGRES_USER=proposalcreator
POSTGRES_DB=proposalcreator
POSTGRES_PASSWORD=$(secret 24)
SECRET_KEY=$(secret 32)
N8N_SHARED_SECRET=$(secret 32)
N8N_ENCRYPTION_KEY=$(secret 32)

# --- Access --------------------------------------------------------------
# Private workspace: accounts are created with
#   docker compose -f docker-compose.prod.yml exec backend python -m app.cli create-user --email you@example.com
ALLOW_REGISTRATION=false
HTTP_PORT=8080
TIMEZONE=Asia/Kolkata
EOF

echo "Created deploy/.env with fresh secrets."
echo "Next: add GEMINI_API_KEY (or ANTHROPIC_API_KEY) to deploy/.env, then run"
echo "  docker compose -f docker-compose.prod.yml up -d --build"
